<script lang="ts">import { stepIndicatorClassName } from '@fex-design/styles/steps'; import { cn } from '@fex/utils'; import { getContext, type Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import CheckIcon from '../../icon/check.svelte'; import { stepContextKey } from './context'; interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'class' | 'children'> { class?: string; children?: Snippet }; let { class: className, children, ...rest }: Props = $props(); const step = getContext<any>(stepContextKey); if (!step) throw new Error('StepIndicator must be used inside Step.')</script>
<span {...rest} class={cn(stepIndicatorClassName, className)}>{#if children}{@render children()}{:else if step.info.status === 'finish'}<CheckIcon />{:else}{step.position}{/if}</span>
